-- Arauto hub: core schema (connection, audit, peers, notices).
--
-- Rules that hold for every migration (docs/15-mvp.md, section 2):
--   * time is BIGINT milliseconds UTC, always given by the hub; never the database clock,
--     and no time defaults;
--   * identifiers are UUIDs generated by the hub;
--   * every business table carries organization_id;
--   * the WhatsApp tables (engine, number, chat, access, engine_event) come in 0002.

-- ---------------------------------------------------------------------------- installation

CREATE TABLE installation (
    singleton           BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (singleton),
    created_at          BIGINT  NOT NULL,
    restored_mode       BOOLEAN NOT NULL DEFAULT FALSE,
    restored_at         BIGINT,
    restored_copy_of    BIGINT,
    CHECK (restored_mode OR (restored_at IS NULL AND restored_copy_of IS NULL))
);

CREATE TABLE hub_key (
    id                  UUID PRIMARY KEY,
    public_key          BYTEA  NOT NULL CHECK (octet_length(public_key) = 32),
    private_key_enc     BYTEA  NOT NULL,
    state               TEXT   NOT NULL CHECK (state IN ('active', 'retired')),
    created_at          BIGINT NOT NULL
);
CREATE UNIQUE INDEX hub_key_one_active ON hub_key ((TRUE)) WHERE state = 'active';

CREATE TABLE organization (
    id                  UUID PRIMARY KEY,
    name                TEXT   NOT NULL,
    state               TEXT   NOT NULL CHECK (state IN ('active', 'suspended')),
    key_enc             BYTEA  NOT NULL,
    created_at          BIGINT NOT NULL
);

CREATE TABLE admin (
    id                  UUID PRIMARY KEY,
    organization_id     UUID   NOT NULL REFERENCES organization (id),
    name                TEXT   NOT NULL,
    kind                TEXT   NOT NULL CHECK (kind IN ('local')),
    created_at          BIGINT NOT NULL,
    UNIQUE (organization_id, name)
);

CREATE TABLE retention (
    table_name          TEXT PRIMARY KEY,
    days                INTEGER NOT NULL CHECK (days > 0)
);
INSERT INTO retention (table_name, days) VALUES
    ('peer_message', 30),
    ('tool_call', 7),
    ('notice', 7),
    ('channel_connection', 90),
    ('unknown_device', 90);

-- ---------------------------------------------------------------------------- hermes and devices

CREATE TABLE hermes (
    id                  UUID PRIMARY KEY,
    organization_id     UUID   NOT NULL REFERENCES organization (id),
    -- The only admin-given text that reaches the LLM: restricted, immutable, never reused.
    name                TEXT   NOT NULL CHECK (name ~ '^[a-z0-9][a-z0-9_-]{0,31}$'),
    mode                TEXT   NOT NULL DEFAULT 'fast' CHECK (mode IN ('fast', 'shielded')),
    can_be_woken        BOOLEAN NOT NULL DEFAULT FALSE,
    wake_reason         TEXT,
    created_at          BIGINT NOT NULL,
    deleted_at          BIGINT,
    UNIQUE (organization_id, name),
    UNIQUE (organization_id, id)
);

CREATE TABLE device (
    id                  UUID PRIMARY KEY,
    organization_id     UUID   NOT NULL,
    hermes_id           UUID   NOT NULL,
    public_key          BYTEA  NOT NULL UNIQUE CHECK (octet_length(public_key) = 32),
    state               TEXT   NOT NULL CHECK (state IN (
                            'pending', 'approved', 'active', 'quarantined', 'suspended',
                            'denied', 'expired', 'replaced', 'revoked')),
    state_reason        TEXT,
    state_since         BIGINT NOT NULL,
    -- 'request' until the first credential is confirmed, 'in_use' after it, NULL when final.
    slot                TEXT   CHECK (slot IN ('in_use', 'request')),
    first_confirmed_at  BIGINT,
    current_generation  BIGINT NOT NULL DEFAULT 0 CHECK (current_generation >= 0),
    current_digest      BYTEA  CHECK (current_digest IS NULL OR octet_length(current_digest) = 32),
    pending_generation  BIGINT,
    pending_digest      BYTEA  CHECK (pending_digest IS NULL OR octet_length(pending_digest) = 32),
    max_generation      BIGINT NOT NULL DEFAULT 0 CHECK (max_generation >= 0),
    verification_code   TEXT   CHECK (verification_code IS NULL OR verification_code ~ '^[0-9]{6}$'),
    confirm_until       BIGINT,
    approved_until      BIGINT,
    code_attempts       INTEGER NOT NULL DEFAULT 0,
    enrollments         INTEGER NOT NULL DEFAULT 0,
    declared            JSONB  NOT NULL DEFAULT '{}'::jsonb,
    enrolled_from       TEXT,
    connector_version   TEXT,
    proto               INTEGER,
    created_at          BIGINT NOT NULL,
    approved_by         UUID   REFERENCES admin (id),
    approved_at         BIGINT,
    last_contact_at     BIGINT,
    last_address        TEXT,
    marked_by_restoration BOOLEAN NOT NULL DEFAULT FALSE,
    FOREIGN KEY (organization_id, hermes_id) REFERENCES hermes (organization_id, id),
    CHECK ((slot IS NULL) = (state IN ('denied', 'expired', 'replaced', 'revoked'))),
    CHECK (slot IS DISTINCT FROM 'in_use' OR first_confirmed_at IS NOT NULL),
    CHECK (slot IS DISTINCT FROM 'request' OR first_confirmed_at IS NULL),
    CHECK (state NOT IN ('pending', 'approved') OR slot = 'request'),
    CHECK (state NOT IN ('active', 'suspended') OR slot = 'in_use'),
    CHECK ((current_digest IS NULL) = (current_generation = 0)),
    CHECK ((pending_digest IS NULL) = (pending_generation IS NULL)),
    CHECK (max_generation >= current_generation),
    CHECK (pending_generation IS NULL OR max_generation >= pending_generation)
);
-- At most one device in use and one request in progress per Hermes.
CREATE UNIQUE INDEX device_slot ON device (hermes_id, slot) WHERE slot IS NOT NULL;
CREATE INDEX device_hermes ON device (hermes_id);
CREATE INDEX device_open_deadlines ON device (state) WHERE slot IS NOT NULL;

CREATE TABLE unknown_device (
    id                  UUID PRIMARY KEY,
    organization_id     UUID   NOT NULL REFERENCES organization (id),
    public_key          BYTEA  NOT NULL CHECK (octet_length(public_key) = 32),
    declared            JSONB  NOT NULL DEFAULT '{}'::jsonb,
    address             TEXT,
    seen_at             BIGINT NOT NULL,
    UNIQUE (organization_id, public_key)
);

CREATE TABLE invite (
    id                  UUID PRIMARY KEY,
    organization_id     UUID   NOT NULL,
    hermes_id           UUID   NOT NULL,
    -- SHA-256 of the 32 invite bytes. Never the invite. Erased when it expires unused.
    digest              BYTEA  CHECK (digest IS NULL OR octet_length(digest) = 32),
    state               TEXT   NOT NULL CHECK (state IN ('issued', 'used', 'expired', 'cancelled')),
    created_by          UUID   REFERENCES admin (id),
    created_at          BIGINT NOT NULL,
    expires_at          BIGINT NOT NULL,
    used_at             BIGINT,
    device_id           UUID   REFERENCES device (id),
    FOREIGN KEY (organization_id, hermes_id) REFERENCES hermes (organization_id, id),
    CHECK (state <> 'issued' OR digest IS NOT NULL),
    CHECK ((state = 'used') = (device_id IS NOT NULL))
);
CREATE UNIQUE INDEX invite_digest ON invite (digest) WHERE digest IS NOT NULL;
CREATE UNIQUE INDEX invite_one_issued ON invite (hermes_id) WHERE state = 'issued';

CREATE TABLE channel_connection (
    id                  UUID PRIMARY KEY,
    organization_id     UUID   NOT NULL REFERENCES organization (id),
    device_id           UUID   NOT NULL REFERENCES device (id),
    address             TEXT,
    connector_version   TEXT,
    opened_at           BIGINT NOT NULL,
    credential_issued_at BIGINT,
    swap_confirmed_at   BIGINT,
    closed_at           BIGINT,
    close_reason        TEXT
);
CREATE INDEX channel_connection_device ON channel_connection (device_id, opened_at);
CREATE INDEX channel_connection_opened ON channel_connection (opened_at);

-- ---------------------------------------------------------------------------- audit and alerts

CREATE SEQUENCE audit_seq;

CREATE TABLE audit (
    seq                 BIGINT PRIMARY KEY DEFAULT nextval('audit_seq'),
    organization_id     UUID   REFERENCES organization (id),
    at                  BIGINT NOT NULL,
    actor_kind          TEXT   NOT NULL CHECK (actor_kind IN ('admin', 'device', 'system')),
    actor_id            UUID,
    actor_note          TEXT,
    action              TEXT   NOT NULL,
    target_kind         TEXT,
    target_id           UUID,
    address             TEXT,
    result              TEXT   NOT NULL CHECK (result IN ('ok', 'denied', 'error')),
    code                TEXT,
    -- A security event changes who can do what; the mark outside the database follows these.
    security            BOOLEAN NOT NULL,
    details             JSONB  NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX audit_security ON audit (seq) WHERE security;
CREATE INDEX audit_org_at ON audit (organization_id, at);

-- Append-only. This guards against a bug in the program; whoever owns the database can
-- still drop the triggers.
CREATE FUNCTION audit_is_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit is append-only';
END;
$$;
CREATE TRIGGER audit_no_update BEFORE UPDATE OR DELETE ON audit
    FOR EACH ROW EXECUTE FUNCTION audit_is_append_only();
CREATE TRIGGER audit_no_truncate BEFORE TRUNCATE ON audit
    FOR EACH STATEMENT EXECUTE FUNCTION audit_is_append_only();

CREATE TABLE alert (
    id                  UUID PRIMARY KEY,
    organization_id     UUID   NOT NULL REFERENCES organization (id),
    kind                TEXT   NOT NULL,
    hermes_id           UUID,
    device_id           UUID,
    at                  BIGINT NOT NULL,
    details             JSONB  NOT NULL DEFAULT '{}'::jsonb,
    seen_at             BIGINT
);
CREATE INDEX alert_org_at ON alert (organization_id, at);

CREATE TABLE tool_call (
    id                  BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    organization_id     UUID   NOT NULL REFERENCES organization (id),
    hermes_id           UUID   NOT NULL,
    device_id           UUID   NOT NULL,
    tool                TEXT   NOT NULL,
    result              TEXT   NOT NULL CHECK (result IN ('ok', 'denied', 'error')),
    code                TEXT,
    duration_ms         INTEGER NOT NULL,
    -- Repeated refusals with the same code are counted here instead of one row each.
    repeats             INTEGER NOT NULL DEFAULT 1 CHECK (repeats >= 1),
    at                  BIGINT NOT NULL
);
CREATE INDEX tool_call_at ON tool_call (at);

-- ---------------------------------------------------------------------------- conversation between Hermes

CREATE TABLE peer_link (
    organization_id     UUID   NOT NULL,
    from_hermes_id      UUID   NOT NULL,
    to_hermes_id        UUID   NOT NULL,
    wake                BOOLEAN NOT NULL DEFAULT FALSE,
    created_by          UUID   REFERENCES admin (id),
    created_at          BIGINT NOT NULL,
    changed_at          BIGINT NOT NULL,
    PRIMARY KEY (from_hermes_id, to_hermes_id),
    FOREIGN KEY (organization_id, from_hermes_id) REFERENCES hermes (organization_id, id),
    FOREIGN KEY (organization_id, to_hermes_id) REFERENCES hermes (organization_id, id),
    CHECK (from_hermes_id <> to_hermes_id)
);
CREATE INDEX peer_link_to ON peer_link (to_hermes_id);

CREATE TABLE peer_thread (
    id                  UUID PRIMARY KEY,
    organization_id     UUID   NOT NULL,
    -- The two participants, smaller id first.
    hermes_a            UUID   NOT NULL,
    hermes_b            UUID   NOT NULL,
    created_at          BIGINT NOT NULL,
    last_message_at     BIGINT NOT NULL,
    FOREIGN KEY (organization_id, hermes_a) REFERENCES hermes (organization_id, id),
    FOREIGN KEY (organization_id, hermes_b) REFERENCES hermes (organization_id, id),
    CHECK (hermes_a < hermes_b)
);
CREATE INDEX peer_thread_a ON peer_thread (hermes_a, last_message_at DESC);
CREATE INDEX peer_thread_b ON peer_thread (hermes_b, last_message_at DESC);

CREATE TABLE peer_message (
    id                  UUID PRIMARY KEY,
    organization_id     UUID   NOT NULL REFERENCES organization (id),
    thread_id           UUID   NOT NULL REFERENCES peer_thread (id),
    from_hermes_id      UUID   NOT NULL,
    to_hermes_id        UUID   NOT NULL,
    sent_at             BIGINT NOT NULL,
    size                INTEGER NOT NULL CHECK (size BETWEEN 1 AND 16384),
    nonce               BYTEA  NOT NULL CHECK (octet_length(nonce) = 24),
    text_enc            BYTEA  NOT NULL,
    read_at             BIGINT,
    -- TRUE when this message created a new wake-up notice (counted by the notice ceilings).
    woke                BOOLEAN NOT NULL DEFAULT FALSE,
    purge_at            BIGINT NOT NULL,
    CHECK (from_hermes_id <> to_hermes_id)
);
CREATE INDEX peer_message_thread ON peer_message (thread_id, sent_at, id);
CREATE INDEX peer_message_from ON peer_message (from_hermes_id, sent_at);
CREATE INDEX peer_message_pair ON peer_message (from_hermes_id, to_hermes_id, sent_at);
CREATE INDEX peer_message_unread ON peer_message (to_hermes_id, from_hermes_id) WHERE read_at IS NULL;
CREATE INDEX peer_message_woke ON peer_message (to_hermes_id, sent_at) WHERE woke;
CREATE INDEX peer_message_purge ON peer_message (purge_at);

-- ---------------------------------------------------------------------------- notices (outbox)

CREATE TABLE notice (
    id                  UUID PRIMARY KEY,
    organization_id     UUID   NOT NULL REFERENCES organization (id),
    hermes_id           UUID   NOT NULL,
    kind                TEXT   NOT NULL CHECK (kind IN ('whatsapp', 'peer')),
    -- Target of a 'whatsapp' notice (foreign keys are added with the WhatsApp tables).
    number_id           UUID,
    chat_id             UUID,
    -- Target of a 'peer' notice.
    from_hermes_id      UUID,
    count               INTEGER NOT NULL CHECK (count BETWEEN 1 AND 9999),
    state               TEXT   NOT NULL CHECK (state IN (
                            'pending', 'sent', 'confirmed', 'expired', 'discarded')),
    attempts            INTEGER NOT NULL DEFAULT 0,
    not_before          BIGINT NOT NULL,
    leased_until        BIGINT,
    sent_at             BIGINT,
    created_at          BIGINT NOT NULL,
    expires_at          BIGINT NOT NULL,
    resolved_at         BIGINT,
    FOREIGN KEY (organization_id, hermes_id) REFERENCES hermes (organization_id, id),
    CHECK ((kind = 'whatsapp') = (number_id IS NOT NULL AND chat_id IS NOT NULL)),
    CHECK ((kind = 'peer') = (from_hermes_id IS NOT NULL)),
    CHECK ((state = 'sent') = (leased_until IS NOT NULL)),
    CHECK ((state IN ('confirmed', 'expired', 'discarded')) = (resolved_at IS NOT NULL))
);
-- One pending notice per Hermes and target: whatever arrives next adds to the count.
CREATE UNIQUE INDEX notice_pending_whatsapp ON notice (hermes_id, chat_id)
    WHERE kind = 'whatsapp' AND state = 'pending';
CREATE UNIQUE INDEX notice_pending_peer ON notice (hermes_id, from_hermes_id)
    WHERE kind = 'peer' AND state = 'pending';
CREATE INDEX notice_open ON notice (hermes_id, not_before) WHERE state IN ('pending', 'sent');
CREATE INDEX notice_resolved ON notice (resolved_at) WHERE resolved_at IS NOT NULL;
